## 7. 用 aclnn 在 C/C++ 中调用（PyTorch 接入的底层）

S4 原文 `main.cpp`（完整可对照）：

```cpp
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include "acl/acl.h"
#include "aclnn/aclnn_base.h"
#include "aclnn_add_custom.h"

#define CHECK_ACL(call) \
    do { \
        aclnnStatus status = (call); \
        if (status != ACL_SUCCESS) { \
            printf("ACL Error: %d at %s:%d\n", status, __FILE__, __LINE__); \
            return -1; \
        } \
    } while (0)

#define CHECK_RTL(call) \
    do { \
        aclError err = (call); \
        if (err != ACL_SUCCESS) { \
            printf("ACL RT Error: %d at %s:%d\n", err, __FILE__, __LINE__); \
            return -1; \
        } \
    } while (0)

int main()
{
    CHECK_ACL(aclnnInit(nullptr));
    const int32_t deviceId = 0;
    CHECK_RTL(aclrtSetDevice(deviceId));
    aclrtStream stream = nullptr;
    CHECK_RTL(aclrtCreateStream(&stream));

    const int count = 1024;
    size_t bufferSize = count * sizeof(float);
    std::vector<float> input0Host(count), input1Host(count), outputHost(count, 0.0f);
    for (int i = 0; i < count; i++) { input0Host[i] = (float)i; input1Host[i] = (float)i; }

    void *input0DeviceMem = nullptr, *input1DeviceMem = nullptr, *outputDeviceMem = nullptr;
    CHECK_RTL(aclrtMalloc(&input0DeviceMem, bufferSize, ACL_MEM_MALLOC_HUGE_FIRST));
    CHECK_RTL(aclrtMalloc(&input1DeviceMem, bufferSize, ACL_MEM_MALLOC_HUGE_FIRST));
    CHECK_RTL(aclrtMalloc(&outputDeviceMem, bufferSize, ACL_MEM_MALLOC_HUGE_FIRST));
    CHECK_RTL(aclrtMemcpy(input0DeviceMem, bufferSize, input0Host.data(), bufferSize, ACL_MEMCPY_HOST_TO_DEVICE));
    CHECK_RTL(aclrtMemcpy(input1DeviceMem, bufferSize, input1Host.data(), bufferSize, ACL_MEMCPY_HOST_TO_DEVICE));

    int64_t shape[] = {count};
    uint64_t shapeNum = 1;
    aclTensor *input0 = aclCreateTensor(shape, shapeNum, ACL_FLOAT, nullptr, 0, ACL_FORMAT_ND, shape, shapeNum, input0DeviceMem);
    aclTensor *input1 = aclCreateTensor(shape, shapeNum, ACL_FLOAT, nullptr, 0, ACL_FORMAT_ND, shape, shapeNum, input1DeviceMem);
    aclTensor *output = aclCreateTensor(shape, shapeNum, ACL_FLOAT, nullptr, 0, ACL_FORMAT_ND, shape, shapeNum, outputDeviceMem);

    uint64_t workspaceSize = 0;
    aclOpExecutor *executor = nullptr;
    CHECK_ACL(aclnnAddCustomGetWorkspaceSize(input0, input1, output, &workspaceSize, &executor));

    void *workspaceDeviceMem = nullptr;
    if (workspaceSize > 0) {
        CHECK_RTL(aclrtMalloc(&workspaceDeviceMem, workspaceSize, ACL_MEM_MALLOC_HUGE_FIRST));
    }
    CHECK_ACL(aclnnAddCustom(workspaceDeviceMem, workspaceSize, executor, stream));
    CHECK_RTL(aclrtSynchronizeStream(stream));
    CHECK_RTL(aclrtMemcpy(outputHost.data(), bufferSize, outputDeviceMem, bufferSize, ACL_MEMCPY_DEVICE_TO_HOST));
    // ... 校验 outputHost[i] == input0Host[i] + input1Host[i]，打印 test pass

    aclDestroyTensor(input0); aclDestroyTensor(input1); aclDestroyTensor(output);
    aclDestroyAclOpExecutor(executor);
    if (workspaceDeviceMem) aclrtFree(workspaceDeviceMem);
    aclrtFree(input0DeviceMem); aclrtFree(input1DeviceMem); aclrtFree(outputDeviceMem);
    CHECK_RTL(aclrtDestroyStream(stream));
    CHECK_RTL(aclrtResetDevice(deviceId));
    aclnnFinalize();
    return 0;
}
```

